mapper.select:
SELECT pt.id, pt.project_id, pt.stage_key, pt.task_key, pt.name, pt.description, pt.status, pt.start_date, pt.end_date, pt.progress, pt.manager_id, pt.participant_ids, pt.created_by, pt.created_at, pt.updated_by, pt.updated_at, pt.deleted, p.name AS project_name, s.name AS stage_name, u.name AS manager_name, ( SELECT GROUP_CONCAT(u2.name SEPARATOR ', ') FROM t_user u2 WHERE FIND_IN_SET(u2.id, pt.participant_ids) ) AS participant_names FROM t_project_task pt LEFT JOIN t_project p ON pt.project_id = p.id AND p.deleted = 0 LEFT JOIN t_stage s ON pt.stage_key = s.`key` AND s.deleted = 0 LEFT JOIN t_user u ON pt.manager_id = u.id AND u.deleted = 0 WHERE pt.deleted = 0
AND pt.project_id = #{projectId}
AND pt.status = #{status}
AND pt.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY pt.start_date ASC
